class A:
    def test(self):
        return "A"

class B:
    def test(self):
        return "B"

class C(A, B):
    def test(self):
        return super(A, self).test()

c = C()
print(c.test())

class A:
    def greet(self):
        return "Hello"

class B(A):
    def greet(self):
        def inner():
            return super().greet() + " World"
        return inner()

b = B()
print(b.greet())

